import java.util.*;

class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null) return null;

        int n = 0;
        for (ListNode p = head; p != null; p = p.next) n++;

        int[] arr = new int[n];
        int i = 0;
        for (ListNode p = head; p != null; p = p.next) arr[i++] = p.val;

        Arrays.sort(arr);

        i = 0;
        for (ListNode p = head; p != null; p = p.next) p.val = arr[i++];
        return head;
    }
}

class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;

        int n = 0;
        for (ListNode p = head; p != null; p = p.next) n++;

        ListNode dummy = new ListNode(0);
        dummy.next = head;

        for (int len = 1; len < n; len *= 2) {
            ListNode prev = dummy, cur = dummy.next;
            while (cur != null) {
                // 切第一段
                ListNode first = cur;
                int cnt = 1;
                while (cnt < len && cur.next != null) { cur = cur.next; cnt++; }

                // 切第二段
                ListNode second = cur.next;
                cur.next = null;         // 断开第一段
                cur = second;
                cnt = 1;
                while (cnt < len && cur != null && cur.next != null) { cur = cur.next; cnt++; }

                ListNode next = null;
                if (cur != null) { next = cur.next; cur.next = null; }   // 断开第二段

                // 合并两段接到 prev 后
                ListNode merged = mergeTwo(first, second);
                prev.next = merged;
                while (prev.next != null) prev = prev.next;

                cur = next;
            }
        }
        return dummy.next;
    }

    private ListNode mergeTwo(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(0), tail = dummy;
        while (a != null && b != null) {
            if (a.val <= b.val) { tail.next = a; a = a.next; }
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = (a != null) ? a : b;
        return dummy.next;
    }
}

class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;

        // 快慢指针找前半段的最后一个节点
        // fast 从 head.next 出发，保证前半段长度 <= 后半段，不会切出空段
        ListNode slow = head, fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode mid = slow.next;
        slow.next = null;          // 必须断开，否则递归不收敛

        ListNode left = sortList(head);
        ListNode right = sortList(mid);

        return mergeTwo(left, right);
    }

    private ListNode mergeTwo(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(0), tail = dummy;
        while (a != null && b != null) {
            if (a.val <= b.val) { tail.next = a; a = a.next; }
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = (a != null) ? a : b;
        return dummy.next;
    }
}
